      if (!m || !host.isConnected) return;
      const here = [];
      m.trails.forEach((t) => t.steps.forEach((st) => st.entries.forEach((en, k) => {
        const p = m.scopes[en.scope].file.path;
        if (path === '.' || p.startsWith(path + '/')) here.push({ t, st, k, en, direct: p.slice(0, p.lastIndexOf('/')) === path });
      })));
      if (!here.length) return;
      const shown = here.filter((x) => x.direct).length ? here.filter((x) => x.direct) : here.slice(0, 12);
      host.innerHTML = String(section('trails', 'On the trails', fmt.plural(here.length, 'stop') + (shown.length < here.length ? ', ' + shown.length + ' shown' : ''),
