        node.addEventListener('mouseenter', () => svg.querySelectorAll(`.edge[data-from="${name}"], .edge[data-to="${name}"]`).forEach((e) => e.classList.add('hot')));
        node.addEventListener('mouseleave', () => svg.querySelectorAll('.edge.hot').forEach((e) => e.classList.remove('hot')));
      });
      if (route.query.section) { const el = main.querySelector('#section-' + route.query.section); if (el) el.scrollIntoView({ block: 'start' }); }
    },
  };

  // MARK: - A doc of the project

  /** A Markdown file, read on its own page: rendered, its headings beside it to jump to. */
  views.file = {
    title: 'Doc',
    render(route) {
      const m = /^(.*?)(?::(\d+))?$/.exec(route.rest), path = m[1], entry = own(D.docs, path);
      if (!entry) {
        return { main: html`<div class="crumbs"><a href="#/">${D.meta.title}</a></div><h1 class="file-path">${path}</h1><p class="view-lede" style="margin-top:10px">This site renders the project's Markdown and its code; this file is neither. ${Arch.editorHref(path) ? html`<a href="${Arch.editorHref(path)}">Open it in the editor</a>.` : ''}</p>`, inspector: '' };
