          <article class="prose doc-page">${Arch.doc(entry.text, folder)}</article>`,
        inspector: html`<p class="eyebrow">${path}</p>
          ${heads.length ? html`<section><h3>On this page</h3><ul class="reflist doc-toc">${heads.map((h) => html`<li class="${h.level > 2 ? 'sub' : ''}"><a href="#" data-action="scroll-to" data-target="${h.id}">${raw(inline(h.text))}</a></li>`)}</ul></section>` : ''}
          <div class="file-head">${editor ? html`<a class="button" href="${editor}">Open in the editor</a>` : ''}<button type="button" class="button" data-action="copy" data-text="${path}">Copy path</button></div>`,
